#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# INKRUNNER → TestFlight. Run from Git Bash in the repository:
#   bash tools/ios-testflight-wizard.sh
# Setup stages remember what's done (in the Git-ignored .apple folder), so
# later runs skip straight to building and uploading a new TestFlight build.

TOTAL_STAGES=10

cd "$(dirname "$0")/.."
APPLE_DIR=.apple
ENV_FILE="$APPLE_DIR/testflight.env"
BUNDLE_ID=com.millzach.inkrunner
BRANCH=ios/testflight
DOWNLOADS="$HOME/Downloads"
PYTHON=$(command -v python || command -v python3 || true)

# winpath FILE — the Windows path to show for browser upload dialogs.
winpath() { if command -v cygpath >/dev/null 2>&1; then cygpath -wa "$1"; else printf '%s' "$1"; fi; }

# done_before KEY — true when an earlier run recorded KEY=1.
done_before() { [[ "$(_existing "$1" || true)" == 1 ]]; }

# skip_if_done KEY "what" — succeeds (skip the stage) when it was finished earlier
# and the human doesn't want to repeat it.
skip_if_done() {
  done_before "$1" || return 1
  note "Done on an earlier run: $2."
  ! confirm "Do it again?"
}

# saved FILE — report a file stored in .apple.
saved() { printf '  %s✓ saved%s %s\n' "$GREEN" "$RESET" "$1"; }

# fetch_download PATTERN DEST "what" — copy the newest matching download into .apple.
fetch_download() {
  local pattern="$1" dest="$2" what="$3" found path
  while :; do
    found=$(ls -t "$DOWNLOADS"/$pattern 2>/dev/null | head -n1 || true)
    if [[ -n "$found" ]] && confirm "Use $(basename "$found") from Downloads as the $what?"; then
      cp "$found" "$dest"; saved "$dest"; return 0
    fi
    printf '  %sPath to the %s (drag the file here, or Enter to look in Downloads again):%s ' "$BOLD" "$what" "$RESET"
    read -r path || true
    path=${path//\"/}
    [[ -z "$path" ]] && continue
    command -v cygpath >/dev/null 2>&1 && path=$(cygpath -u "$path")
    if [[ -f "$path" ]]; then cp "$path" "$dest"; saved "$dest"; return 0; fi
    warn "No file at $path"
  done
}

# cert_matches_key — the saved certificate was issued for this computer's CSR.
cert_matches_key() {
  local cert key
  cert=$(openssl x509 -inform DER -in "$APPLE_DIR/signing.cer" -pubkey -noout 2>/dev/null) || return 1
  key=$(openssl pkey -in "$APPLE_DIR/signing.key" -passin "file:$APPLE_DIR/key-password.txt" -pubout 2>/dev/null) || return 1
  [[ "$cert" == "$key" ]]
}

for tool in git gh openssl; do
  command -v "$tool" >/dev/null 2>&1 || { printf '%s is required. Run this from Git Bash.\n' "$tool"; exit 1; }
done
[[ -n "$PYTHON" ]] || { printf 'Python 3 is required.\n'; exit 1; }
gh auth status >/dev/null 2>&1 || { printf 'Sign in to GitHub first: gh auth login\n'; exit 1; }
for file in signing.key key-password.txt inkrunner.csr; do
  [[ -f "$APPLE_DIR/$file" ]] && continue
  printf 'Missing %s/%s. If Apple already issued a certificate from it, recover the file.\n' "$APPLE_DIR" "$file"
  printf 'Otherwise create a new key and request with: python tools/ios-credentials.py prepare\n'
  exit 1
done

banner "INKRUNNER → TestFlight on your iPhone"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Apple Developer membership"
say "TestFlight needs a paid Apple Developer Program membership (\$99/year)."
open_url "https://developer.apple.com/account"
step "Sign in with the Apple ID you'll use on your iPhone."
step "Scroll to Membership details and check it says Apple Developer Program."
step "Find the Team ID there. Sol configured 6B7FL8Z7PX."
note "No membership yet? Enroll at https://developer.apple.com/programs/enroll/,"
note "wait for Apple's approval email, then re-run this wizard."
TEAM_ID=""
until [[ "$TEAM_ID" =~ ^[A-Z0-9]{10}$ ]]; do
  ask TEAM_ID "Team ID (Enter for 6B7FL8Z7PX):"
  TEAM_ID=${TEAM_ID:-6B7FL8Z7PX}
  [[ "$TEAM_ID" =~ ^[A-Z0-9]{10}$ ]] || warn "A Team ID is 10 capital letters or digits."
done
write_env TEAM_ID "$TEAM_ID"
pause "Press Enter to continue"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Register the app's bundle ID"
if ! skip_if_done DONE_BUNDLE_ID "bundle ID $BUNDLE_ID registered"; then
  open_url "https://developer.apple.com/account/resources/identifiers/list"
  step "Click the blue + next to Identifiers."
  step "Choose App IDs → Continue → App → Continue."
  step "Description: INKRUNNER"
  step "Bundle ID: Explicit → $BUNDLE_ID"
  step "Leave the capabilities as they are → Continue → Register."
  note "If Apple says it's already registered to your team, that's fine."
  warn "If it belongs to a different team, press Ctrl-C and tell Claude."
  pause "Press Enter once $BUNDLE_ID shows in the Identifiers list"
  write_env DONE_BUNDLE_ID 1
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Create the App Store Connect app record"
if ! skip_if_done DONE_APP_RECORD "app record created"; then
  open_url "https://appstoreconnect.apple.com/apps"
  step "Click the blue + → New App."
  step "Platforms: iOS"
  step "Name: INKRUNNER  (if taken, try INKRUNNER 墨 or INKRUNNER Ink Runner)"
  step "Primary Language: English (U.S.)"
  step "Bundle ID: INKRUNNER - $BUNDLE_ID"
  step "SKU: inkrunner-ios"
  step "User Access: Full Access → Create."
  note "This name is only the store listing; the home-screen name stays INKRUNNER."
  pause "Press Enter once the app's page opens in App Store Connect"
  write_env DONE_APP_RECORD 1
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Distribution certificate"
if [[ -f "$APPLE_DIR/signing.cer" ]] && cert_matches_key; then
  note "Already saved $APPLE_DIR/signing.cer, and it matches this computer's key."
else
  say "Apple issues a certificate for the signing key that already lives in .apple."
  open_url "https://developer.apple.com/account/resources/certificates/list"
  step "Click the blue + next to Certificates."
  step "Under Software choose Apple Distribution → Continue."
  step "Choose File → select this exact file:"
  say "    $(winpath "$APPLE_DIR/inkrunner.csr")"
  step "Continue → Download (saves distribution.cer to Downloads)."
  warn "If Apple says you've reached the certificate limit, do NOT revoke anything."
  warn "Press Ctrl-C and ask Claude; revoking can break signing elsewhere."
  pause "Press Enter once the .cer has downloaded"
  until cert_matches_key; do
    rm -f "$APPLE_DIR/signing.cer"
    fetch_download "*.cer" "$APPLE_DIR/signing.cer" "distribution certificate"
    cert_matches_key || warn "That certificate wasn't issued for inkrunner.csr. Pick the one you just downloaded."
  done
  printf '  %s✓ certificate matches the signing key in .apple%s\n' "$GREEN" "$RESET"
fi
pause "Press Enter to continue"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "App Store provisioning profile"
if [[ -f "$APPLE_DIR/profile.mobileprovision" ]] && ! confirm "A profile is already saved. Replace it with a new one?"; then
  note "Keeping $APPLE_DIR/profile.mobileprovision (stage 7 checks it fully)."
else
  open_url "https://developer.apple.com/account/resources/profiles/list"
  step "Click the blue + next to Profiles."
  step "Under Distribution choose App Store Connect (older label: App Store) → Continue."
  step "App ID: INKRUNNER ($TEAM_ID.$BUNDLE_ID) → Continue."
  step "Tick the Apple Distribution certificate from stage 4 (latest expiry date) → Continue."
  step "Provisioning Profile Name: INKRUNNER TestFlight → Generate → Download."
  pause "Press Enter once the .mobileprovision has downloaded"
  fetch_download "*.mobileprovision" "$APPLE_DIR/profile.mobileprovision" "provisioning profile"
fi
pause "Press Enter to continue"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "App Store Connect API key (lets GitHub upload builds)"
KEY_FILE=$(ls -t "$APPLE_DIR"/AuthKey_*.p8 2>/dev/null | head -n1 || true)
ISSUER_ID=$(_existing ISSUER_ID || true)
if [[ -n "$KEY_FILE" && -n "$ISSUER_ID" ]] && ! confirm "API key $(basename "$KEY_FILE") is saved. Make a new one?"; then
  note "Keeping $(basename "$KEY_FILE")."
else
  open_url "https://appstoreconnect.apple.com/access/integrations/api"
  step "Open the Team Keys tab. First time? Click Request Access and accept the terms."
  step "Click + (Generate API Key). Name: INKRUNNER GitHub. Access: App Manager → Generate."
  step "Click Download on the new key's row. Apple allows this only ONCE."
  warn "Never paste the key file's contents into chat or commit it."
  pause "Press Enter once AuthKey_XXXXXXXXXX.p8 has downloaded"
  KEY_FILE=""
  until [[ -n "$KEY_FILE" ]]; do
    found=$(ls -t "$DOWNLOADS"/AuthKey_*.p8 2>/dev/null | head -n1 || true)
    if [[ -n "$found" ]] && confirm "Use $(basename "$found") from Downloads?"; then
      cp "$found" "$APPLE_DIR/"
      KEY_FILE="$APPLE_DIR/$(basename "$found")"
      saved "$KEY_FILE"
    else
      warn "Put AuthKey_*.p8 in $DOWNLOADS, then press Enter."
      pause ""
    fi
  done
  step "On the Team Keys page, copy the Issuer ID shown above the keys table."
  ISSUER_ID=""
  until [[ "$ISSUER_ID" =~ ^[A-Fa-f0-9-]{36}$ ]]; do
    ask ISSUER_ID "Issuer ID (36 characters, like 57246542-96fe-1a63-e053-0824d011072a):"
    [[ "$ISSUER_ID" =~ ^[A-Fa-f0-9-]{36}$ ]] || warn "That doesn't look like an Issuer ID."
  done
  write_env ISSUER_ID "$ISSUER_ID"
fi
KEY_ID=$(basename "$KEY_FILE" .p8)
KEY_ID=${KEY_ID#AuthKey_}
note "Key ID (from the file name): $KEY_ID"
write_env KEY_ID "$KEY_ID"
pause "Press Enter to continue"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Check everything and save it to GitHub"
existing=$(gh secret list --json name --jq '.[].name' 2>/dev/null || true)
missing=0
for name in IOS_CERTIFICATE_BASE64 IOS_CERTIFICATE_PASSWORD IOS_PROFILE_BASE64 ASC_KEY_ID ASC_ISSUER_ID ASC_PRIVATE_KEY; do
  grep -qx "$name" <<<"$existing" || missing=1
done
if (( missing == 0 )) && ! confirm "GitHub already has every signing secret. Save them again from these files?"; then
  note "Keeping the GitHub secrets already saved."
else
  say "Checking that the certificate, profile and API key belong together, then"
  say "saving them as encrypted GitHub Actions secrets. Nothing secret is printed."
  until "$PYTHON" tools/ios-credentials.py configure --team-id "$TEAM_ID" --key-id "$KEY_ID" --issuer-id "$ISSUER_ID"; do
    warn "The check failed (reason above). Common fixes:"
    note "  profile for another app or certificate → re-run and replace the profile in stage 5"
    note "  wrong Issuer ID → re-run and make a new key in stage 6"
    confirm "Try again now?" || exit 1
  done
  WRITTEN_SECRET+=(IOS_CERTIFICATE_BASE64 IOS_CERTIFICATE_PASSWORD IOS_PROFILE_BASE64 ASC_KEY_ID ASC_ISSUER_ID ASC_PRIVATE_KEY)
fi
pause "Press Enter to continue"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Build, sign and upload to Apple"
git fetch -q origin "$BRANCH" --tags
SHA=$(git rev-parse "origin/$BRANCH")
say "Building the latest pushed commit on $BRANCH:"
say "    $(git log -1 --format='%h %s' "$SHA")"
last=$({ git ls-remote --tags origin 'ios-testflight-*'; git tag -l 'ios-testflight-*' | sed 's#^#refs/tags/#'; } \
  | sed -n 's#.*refs/tags/ios-testflight-\([0-9][0-9]*\)$#\1#p' | sort -n | tail -n1)
TAG="ios-testflight-$(( ${last:-0} + 1 ))"
note "GitHub's Mac runner retests it in the simulator, then archives, signs and uploads (~10 min)."
if confirm "Push tag $TAG to start the upload?"; then
  git tag "$TAG" "$SHA"
  git push -q origin "$TAG"
  say "Waiting for GitHub to start the run…"
  RUN_ID=""
  for _ in $(seq 1 30); do
    RUN_ID=$(gh run list --workflow ios.yml --event push --limit 20 --json databaseId,headBranch \
      --jq ".[] | select(.headBranch==\"$TAG\") | .databaseId" 2>/dev/null | head -n1 || true)
    [[ -n "$RUN_ID" ]] && break
    sleep 5
  done
  if [[ -z "$RUN_ID" ]]; then
    warn "The run didn't appear. Check https://github.com/millZach/inkrunner/actions"
    pause "Press Enter once it has finished successfully"
  elif gh run watch "$RUN_ID" --exit-status --interval 20; then
    printf '  %s✓ Uploaded to App Store Connect%s\n' "$GREEN" "$RESET"
  else
    warn "The run failed. Last lines of the failing step:"
    gh run view "$RUN_ID" --log-failed 2>/dev/null | tail -n 30 || true
    note "Full log: https://github.com/millZach/inkrunner/actions/runs/$RUN_ID"
    note "Share that link with Claude. Re-running the wizard skips ahead and uses the next tag."
    exit 1
  fi
else
  SKIPPED+=("Upload a build: git tag $TAG origin/$BRANCH && git push origin $TAG")
fi
pause "Press Enter to continue"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Make the build available to you in TestFlight"
open_url "https://appstoreconnect.apple.com/apps"
step "Open INKRUNNER → TestFlight tab."
step "The build shows under iOS Builds as Processing. Apple emails you when it's done (5–30 min)."
if done_before DONE_TEST_GROUP; then
  step "Your Internal Testing group should pick it up automatically. Check it's listed there."
else
  step "In the left sidebar, click + next to Internal Testing. Name it: Me."
  step "Tick Enable automatic distribution (later builds then reach you on their own) → Create."
  step "In the group's Testers section click + → tick yourself → Add."
  step "If the build isn't in the group yet: Builds → + → pick it → Add."
fi
note "There should be no encryption questions; the app declares it only uses standard HTTPS."
pause "Press Enter once the build is listed in your Internal Testing group"
write_env DONE_TEST_GROUP 1

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Install on your iPhone"
step "On the iPhone, install TestFlight from the App Store:"
say "    https://apps.apple.com/app/testflight/id899247664"
step "Open TestFlight, signed in with the same Apple ID as your developer account."
step "Tap INKRUNNER → Install (or open the invite email → View in TestFlight)."
step "Turn the ring/silent switch OFF. iOS mutes game audio in silent mode."
pause "Press Enter once INKRUNNER is on your home screen"

finish
printf '%s  What to try on the phone%s\n' "$BOLD" "$RESET"
note "• Paint with one finger while jumping with the other thumb; switch all three ink stones."
note "• Paint near every screen edge; the first edge swipe should stay in the game."
note "• Pause button; switch apps mid-run; come back paused with sound working."
note "• Take a call or ask Siri mid-run; sound should return after Continue."
note "• Finish a scroll, force-quit, reopen; your best time should still be there."
note "• Share a card and the full scroll; try a highlight clip (the riskiest part on iOS)."
note "• Does it run smoothly? Report via TestFlight → INKRUNNER → Send Beta Feedback."
note "Next build: push to $BRANCH, then re-run this wizard. It skips ahead to stage 8."
printf '\n'
